import math

def compute_small(max_n):
    G = [0] * (max_n + 1)
    for x in range(1, max_n + 1):
        reachable = set()
        for y in range(1, x + 1):
            if math.gcd(x, y) == 1:
                reachable.add(G[x - y])
        # Compute mex
        mex = 0
        while mex in reachable:
            mex += 1
        G[x] = mex
    return G

