import sys
import math

# Precompute SPF and prime_le array up to MAX_A = 10,000,000
MAX_A = 10000000

def main():
    # Precompute smallest prime factor for all numbers up to MAX_A
    spf = list(range(MAX_A + 1))  # spf[i] = i initially
    for i in range(2, int(math.isqrt(MAX_A)) + 1):
        if spf[i] == i:  # i is prime
            for j in range(i * i, MAX_A + 1, i):
                if spf[j] == j:
                    spf[j] = i

    # Precompute prime_le[x] = number of primes <= x
    prime_le = [0] * (MAX_A + 1)
    count = 0
    for i in range(MAX_A + 1):
        if spf[i] == i:  # i is prime
            count += 1
        prime_le[i] = count

    # Read input
    input_data = sys.stdin.read().split()
    iterator = iter(input_data)

    try:
        t = int(next(iterator))
    except StopIteration:
        return

    results = []
    for _ in range(t):
        n = int(next(iterator))
        piles = []
        for _ in range(n):
            piles.append(int(next(iterator)))

        xor_sum = 0
        for a in piles:
            if a % 2 == 0:
                g = 0
            else:
                if a == 1:
                    g = 1
                else:
                    sp = spf[a]  # smallest prime factor
                    g = prime_le[sp]  # number of primes <= sp
            xor_sum ^= g

        if xor_sum != 0:
            results.append("Alice")
        else:
            results.append("Bob")

    print('\n'.join(results))

if __name__ == "__main__":
